## Code Example
```javascript
// Sketch: applyDelta(delta)
function applyDelta(state, delta) {
  const { id, op, payload } = delta;
  switch (op) {
    case 'insert': state.set(id, payload); break;
    case 'update': state.set(id, { ...state.get(id), ...payload }); break;
    case 'delete': state.delete(id); break;
  }
  return state;
}
```

